INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000001-0000-0000-0000-000000000001', 'Зачем это нужно', 'Когда ты научишься программировать микроконтроллер, ты сможешь собирать свои игрушки: машинки, которые ездят сами, лампы, которые загораются от хлопка, роботов, которые объезжают препятствия. Всё начинается с одной платы и одной лампочки.', 20),
  (gen_random_uuid(), 'b0000001-0000-0000-0000-000000000001', 'Что будем делать в курсе', 'Сначала заставим светодиод мигать. Потом добавим кнопку, несколько лампочек, научим плату менять яркость и управлять моторчиком. В конце — датчики и настоящие проекты: светофор, ночник, робот на колёсах.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000002-0000-0000-0000-000000000001', 'Где купить', 'Pico и наборы ищи в магазинах электроники, на «Алиэкспресс», в «Чип и Дип» и подобных. Набор «стартовый для Arduino» тоже подойдёт: в нём есть макетная плата, провода, светодиоды и резисторы. Плату потом докупишь Pico отдельно.', 20),
  (gen_random_uuid(), 'b0000002-0000-0000-0000-000000000001', 'Совет', 'Если сомневаешься, какой резистор взять для светодиода — бери 220 Ом или 330 Ом. На корпусе написано цветными полосками; в интернете есть «калькулятор резисторов» по полоскам.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000003-0000-0000-0000-000000000001', 'Почему это важно', 'Pico питается от USB — ток маленький, но если перепутать провода или замкнуть пины, плата может сгореть. Тогда придётся покупать новую. Лучше один раз проверить схему, чем потом грустить.', 20),
  (gen_random_uuid(), 'b0000003-0000-0000-0000-000000000001', 'Запомни правило', 'Длинная нога светодиода — всегда к плюсу (к резистору и пину). Короткая — к минусу (GND). Если перепутаешь — светодиод не загорится, но не сгорит. А вот без резистора подключать нельзя.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000004-0000-0000-0000-000000000001', 'Если Pico не появилась как диск', 'Попробуй другой кабель USB: некоторые кабели только для зарядки, без проводов для данных. Нужен кабель, по которому передаются данные. И зажимай BOOTSEL до того, как вставишь кабель в компьютер.', 20),
  (gen_random_uuid(), 'b0000004-0000-0000-0000-000000000001', 'Где скачать прошивку', 'Зайди на raspberrypi.com → документация → Microcontrollers → Pico. Там раздел «Getting started» и ссылка на файл .uf2 для MicroPython. Скачай и перетащи на диск Pico.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000005-0000-0000-0000-000000000001', 'Как найти плюс и минус на Pico', 'На плате подписаны пины: GP0, GP1, … GP28. Рядом есть пины 3V3 (питание 3.3 В), GND (земля — минус). Светодиод подключаем между любым GPIO (например GP15) и GND. Не подключай к 3V3 напрямую без резистора.', 20),
  (gen_random_uuid(), 'b0000005-0000-0000-0000-000000000001', 'Проверь перед включением', 'Перед тем как вставить USB, ещё раз пройдись по схеме: резистор на месте? Длинная нога светодиода к резистору? Короткая к GND? Тогда можно подключать питание.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000006-0000-0000-0000-000000000001', 'Если светодиод не мигает', 'Проверь: в Thonny выбран интерпретатор MicroPython (Raspberry Pi Pico) и правильный порт. Внизу справа должно быть что-то вроде «Raspberry Pi Pico». Если плата не найдена — выдерни и вставь USB, подожди пару секунд.', 20),
  (gen_random_uuid(), 'b0000006-0000-0000-0000-000000000001', 'Поэкспериментируй', 'Попробуй изменить 0.5 в time.sleep(0.5) на 1 или на 0.2. Светодиод будет мигать реже или чаще. Так ты почувствуешь, что программа слушается твоих команд.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000007-0000-0000-0000-000000000007', 'Если не открывается', 'Wokwi работает в браузере. Включи интернет и попробуй Chrome, Firefox или Edge. На телефоне тоже может открыться, но удобнее на компьютере — больше экран.', 20),
  (gen_random_uuid(), 'b0000007-0000-0000-0000-000000000007', 'Сохранить проект', 'В Wokwi можно нажать «Save» и получить ссылку на свой проект. Сохрани её — потом сможешь открыть тот же код и схему с любого компьютера.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000008-0000-0000-0000-000000000008', 'Частая ошибка', 'Если светодиод горит всё время или мигает сам по себе — скорее всего, не подключен резистор 10 кОм к кнопке (между пином и GND). Без него пин «ловит» помехи и ведёт себя странно. Проверь схему.', 20),
  (gen_random_uuid(), 'b0000008-0000-0000-0000-000000000008', 'Идея на будущее', 'Попробуй потом сделать так: один раз нажал — светодиод включился и горит, нажал ещё раз — выключился. Для этого понадобится запоминать состояние в переменной.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000009-0000-0000-0000-000000000009', 'Разные цвета', 'Светодиоды бывают красные, зелёные, синие, жёлтые, белые. Купи несколько цветов — так «бегущий огонёк» будет красивее. Подключаются все одинаково: через резистор 220 Ом.', 20),
  (gen_random_uuid(), 'b0000009-0000-0000-0000-000000000009', 'Четыре и больше', 'Можешь добавить четвёртый светодиод на GP17 и в коде led4 = Pin(17, Pin.OUT). В цикле управляй всеми четырьмя по очереди. Чем больше лампочек — тем интереснее узор.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000010-0000-0000-0000-000000000010', 'Почему 65535', 'Компьютер и плата любят степени двойки. 65535 — это 2 в степени 16 минус 1. Максимальная «яркость» в коде — 65535, выключено — 0. Половина — 32768. Запомнить не обязательно, главное — больше число, ярче свет.', 20),
  (gen_random_uuid(), 'b0000010-0000-0000-0000-000000000010', 'Другие пины с ШИМ', 'На Pico почти все пины GPIO умеют ШИМ. Если GP15 занят, попробуй GP14 или GP16. Код тот же, меняется только номер пина в Pin(15, ...).', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000011-0000-0000-0000-000000000011', 'Если серво дёргается или не крутится', 'Проверь питание: красный провод — плюс, чёрный или коричневый — минус. Если питаешь от Pico по USB — иногда серво «просаживает» питание. Тогда нужны отдельные батарейки для серво или блок питания 5 В.', 20),
  (gen_random_uuid(), 'b0000011-0000-0000-0000-000000000011', 'Углы под себя', 'Числа 1638 и 8192 у разных серво могут чуть отличаться. Если твой серво не доходит до 0° или 180°, подбери числа: чуть меньше или чуть больше. Запиши свои числа в комментарий в коде.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'Реальные времена', 'На настоящем светофоре красный горит дольше всего, жёлтый — несколько секунд, зелёный — среднее время. Поставь, например: красный 5 сек, жёлтый 2 сек, зелёный 4 сек — и сравни с перекрёстком у дома.', 20),
  (gen_random_uuid(), 'b0000012-0000-0000-0000-000000000012', 'Добавь кнопку пешехода', 'Подключи кнопку: нажал — через пару секунд включается зелёный на 5 секунд, потом снова красный. Так получится «запрос перехода», как на настоящем светофоре у перехода.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000013-0000-0000-0000-000000000013', 'Если показывает странные числа', 'Убедись, что Trig и Echo не перепутаны и подключены к GP17 и GP18. Если датчик далеко от стены или предмета, он может не поймать отражение — тогда будет ошибка или 0. Держи препятствие на расстоянии 5–200 см.', 20),
  (gen_random_uuid(), 'b0000013-0000-0000-0000-000000000013', 'Идея для робота', 'Такой датчик ставят спереди на машинку: если впереди близко препятствие — остановиться или повернуть. В модуле «Робот на колёсах» можно будет добавить это к своей машине.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000014-0000-0000-0000-000000000014', 'Формула для TMP36', 'Напряжение (в вольтах) = adc.read_u16() / 65535 * 3.3. Температура в °C = (напряжение - 0.5) * 100. Проверь в интернете «TMP36 formula» — там могут быть чуть другие числа для твоей партии датчика.', 20),
  (gen_random_uuid(), 'b0000014-0000-0000-0000-000000000014', 'Что можно сделать', 'Можно включить вентилятор, если жарко, или зажечь светодиод, если холодно. Тогда твоя плата будет «умным» термометром с действиями.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'b0000015-0000-0000-0000-000000000015', 'Подбор порога', 'Запусти программу и выведи в консоль значение с ADC (print(adc.read_u16())). Посмотри число, когда темно, и когда светло. Порог поставь посередине. Например: если в темноте 50000, на свету 10000 — порог 30000.', 20),
  (gen_random_uuid(), 'b0000015-0000-0000-0000-000000000015', 'Красивый корпус', 'Положи плату и детали в небольшую коробку, светодиод направь вверх. Прорежь окошко или используй полупрозрачную крышку — получится настоящий ночник у кровати.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'c0000001-0000-0000-0000-000000000001', 'Готовые наборы', 'В магазинах есть наборы «двухколёсный робот Arduino» или «шасси с моторами». Часто в наборе уже есть шасси, колёса, моторы и иногда драйвер. Плату Arduino можно не использовать — возьми нашу Pico и подключи к тому же драйверу.', 20),
  (gen_random_uuid(), 'c0000001-0000-0000-0000-000000000001', 'Батарейки', 'Лучше использовать батарейный отсек на 4 пальчиковых батарейки (4×1.5 В = 6 В) или аккумуляторы. USB- power bank тоже подойдёт, если у него есть выход 5 В и достаточно тока для моторов.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'c0000002-0000-0000-0000-000000000002', 'Если моторы крутятся не в ту сторону', 'Не переживай: просто поменяй местами два провода от мотора к драйверу. Или в коде поменяй 1 и 0 для этого мотора (IN1/IN2 или IN3/IN4). Запомни, какой мотор у тебя «левый» и «правый», чтобы потом не путаться в поворотах.', 20),
  (gen_random_uuid(), 'c0000002-0000-0000-0000-000000000002', 'Перемычка на L298N', 'На плате L298N иногда есть перемычка (джампер) рядом с питанием логики. Если моторы не крутятся при правильном коде — проверь инструкцию к драйверу: возможно, перемычку нужно поставить или снять.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'c0000003-0000-0000-0000-000000000003', 'Робот едет криво', 'Часто один мотор чуть сильнее другого. Потом мы научимся менять скорость через ШИМ (Enable A и Enable B). Пока можно чуть подправить время: например, левый мотор включать на 1.9 сек, правый на 2 сек — робот поедет ровнее.', 20),
  (gen_random_uuid(), 'c0000003-0000-0000-0000-000000000003', 'Стоп в конце', 'Всегда в конце программы ставь все value(0), чтобы моторы выключились. Иначе робот может поехать сам по себе после цикла.', 21);
INSERT INTO lesson_steps (id, lesson_id, title, content, sort_order) VALUES
  (gen_random_uuid(), 'c0000004-0000-0000-0000-000000000004', 'Точный поворот на 90°', 'Время поворота зависит от батареек и поверхности. Засеки на секундомере: сколько секунд нужно, чтобы робот развернулся на 90°. Подставь это число в time.sleep() в коде поворота. Запиши в комментарий в программе.', 20),
  (gen_random_uuid(), 'c0000004-0000-0000-0000-000000000004', 'Объезд препятствия', 'Когда пройдёшь урок про датчик HC-SR04, можно поставить его на робота: впереди близко стена — остановиться, повернуть, поехать снова. Так робот будет сам объезжать препятствия.', 21);
